/**
 * PandamStyle - recognized property names (CE-02.1).
 *
 * The CE-00.1 registry's 1,108 names with their disposition, generated by
 * tools/policy/build-recognized.mjs into recognized.v1.json. Recognition
 * authorizes nothing: it only selects the rule of a PMS_UNSUPPORTED_PROPERTY
 * diagnostic. The file is read on the first such diagnostic, never on a valid
 * compilation.
 */

import recognizedText from 'pandamstyle:recognized-properties';

let entries = null;

/** `{ css, disposition, subkind?, replacement? }` of an authoring key, or null. */
export function recognizedProperty(key) {
  if (typeof key !== 'string') return null;
  if (entries == null) {
    entries = JSON.parse(String(recognizedText())).entries;
  }
  return Object.hasOwn(entries, key) ? entries[key] : null;
}
